func (fl *functionLibrary) dateWrapper(vals []parser.Value, enh *EvalNodeHelper, f func(time.Time) float64) Vector {
	loc := fl.dateLoc
	if loc == nil {
		loc = time.UTC
	}
	if len(vals) == 0 {
		return append(enh.Out,
			Sample{
				Metric: labels.Labels{},
				Point:  Point{V: f(time.Unix(enh.Ts/1000, 0).In(loc))},
			})
	}

	drop := fl.metricNameLabel
	for _, el := range vals[0].(Vector) {
		t := time.Unix(int64(el.V), 0).In(loc)
		metric := el.Metric
		if drop != "" {
			metric = fl.dropCachedName(enh, el.Metric)
		}
		enh.Out = append(enh.Out, Sample{
			Metric: metric,
			Point:  Point{V: f(t)},
		})
	}

	require.NoError(t, a.Commit())

	query, err := engine.NewInstantQuery(storage, nil, "deriv(foo[30m])", timestamp.Time(1493712846939))
	require.NoError(t, err)

	result := query.Exec(context.Background())
	require.NoError(t, result.Err)

	vec, _ := result.Vector()
	require.Equal(t, 1, len(vec), "Expected 1 result, got %d", len(vec))
	require.Equal(t, 0.0, vec[0].V, "Expected 0.0 as value, got %f", vec[0].V)
}

